#include "pattern_provision_protocol.h"
#include "pattern_sha256.h"
#include <string.h>
static int id_valid(const fm1_provision_identity *i){uint32_t a=0,b=0,k;if(!i||i->base!=0x97000u||i->root>=PFS_COUNT||i->peer>=PFS_COUNT||i->root==i->peer)return 0;for(k=0;k<16;k++)a|=i->domain[k];for(k=0;k<32;k++)b|=i->generation[k];return a&&b;}
static int ready(const fm1_provision_protocol *p){return p&&!p->fault&&id_valid(p->identity)&&p->ops&&p->ops->begin&&p->ops->end&&p->ops->permit_provision&&p->ops->faulted;}
static int overlap(const void *a,size_t n,const void *b,size_t m){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return n&&m&&(x<=y?y-x<n:x-y<m);}
static int scratch_safe(const fm1_provision_protocol *p,const pns_namespace *n,const void *s){return s&&!overlap(s,PFS_SECTOR,p,sizeof *p)&&!overlap(s,PFS_SECTOR,p->identity,sizeof *p->identity)&&!overlap(s,PFS_SECTOR,p->ops,sizeof *p->ops)&&(!p->secret||!overlap(s,PFS_SECTOR,p->secret,32))&&!overlap(s,PFS_SECTOR,n,sizeof *n)&&n&&n->store&&!overlap(s,PFS_SECTOR,n->store,sizeof *n->store);}
static int output_safe(const fm1_provision_protocol *p,const pns_namespace *n,const void *out,size_t size){return !overlap(out,size,p,sizeof *p)&&!overlap(out,size,p->identity,sizeof *p->identity)&&!overlap(out,size,p->ops,sizeof *p->ops)&&(!p->secret||!overlap(out,size,p->secret,32))&&!overlap(out,size,n,sizeof *n)&&n->store&&!overlap(out,size,n->store,sizeof *n->store);}
static int matches(const fm1_provision_identity *i,const pns_namespace *n){return n&&n->store&&n->store->read&&n->digest&&n->store->base==i->base&&n->root==i->root&&n->peer==i->peer&&!memcmp(n->expected,i->domain,16);}
int fm1_provision_identity_read(const fm1_provision_protocol *p,fm1_provision_identity *out){if(!ready(p)||!out||overlap(out,sizeof *out,p,sizeof *p)||overlap(out,sizeof *out,p->identity,sizeof *p->identity)||overlap(out,sizeof *out,p->ops,sizeof *p->ops)||(p->secret&&overlap(out,sizeof *out,p->secret,32)))return FM1_PROVISION_DENIED;*out=*p->identity;return FM1_PROVISION_OK;}
static int finish(fm1_provision_protocol *p,uint32_t token,int rc){if(p->ops->end(p->ops->context,token)!=1){p->fault=1;return FM1_PROVISION_FAULT;}return rc;}
static int provision_sector(fm1_provision_protocol *p,uint32_t sector,int *blank,uint8_t hash[32],void *extra,size_t extra_size){pns_namespace *n=0;void *scratch=0;uint32_t token=0,i;uint8_t *data,digest[32];int clear=1,rc;if(!ready(p)||!blank||!hash||sector>=PFS_COUNT)return FM1_PROVISION_DENIED;if(p->ops->begin(p->ops->context,0,&n,&scratch,&token)!=1){if(p->ops->faulted(p->ops->context)){p->fault=1;return FM1_PROVISION_FAULT;}return FM1_PROVISION_IO;}if(!token||!scratch_safe(p,n,scratch)||!matches(p->identity,n)||overlap(scratch,PFS_SECTOR,hash,32)||overlap(scratch,PFS_SECTOR,blank,sizeof *blank)||overlap(hash,32,blank,sizeof *blank)||!output_safe(p,n,hash,32)||!output_safe(p,n,blank,sizeof *blank)||(extra&&(overlap(scratch,PFS_SECTOR,extra,extra_size)||!output_safe(p,n,extra,extra_size))))return finish(p,token,FM1_PROVISION_DENIED);data=scratch;if(n->store->read(n->store->ctx,n->store->base+sector*PFS_SECTOR,data,PFS_SECTOR)||n->digest(n->ctx,data,PFS_SECTOR,digest))rc=FM1_PROVISION_IO;else{for(i=0;i<PFS_SECTOR;i++)if(data[i]!=255u){clear=0;break;}rc=FM1_PROVISION_OK;}rc=finish(p,token,rc);if(rc==FM1_PROVISION_OK){*blank=clear;memcpy(hash,digest,32);}return rc;}
int fm1_provision_sector(fm1_provision_protocol *p,uint32_t sector,int *blank,uint8_t hash[32]){return provision_sector(p,sector,blank,hash,0,0);}
void fm1_provision_disarm(fm1_provision_protocol *p){if(p){p->write_armed=0;p->challenge_live=0;p->arm_valid=0;p->arm_context=0;memset(p->challenge,0,sizeof p->challenge);}}
int fm1_provision_arm_once(fm1_provision_protocol *p,int (*authorize)(void *),void *ctx){if(!ready(p)||p->write_armed||!authorize||authorize(ctx)!=1)return FM1_PROVISION_DENIED;p->write_armed=1;p->arm_valid=authorize;p->arm_context=ctx;return FM1_PROVISION_OK;}
int fm1_provision_commit(fm1_provision_protocol *p,const fm1_provision_identity *request){pns_namespace *n=0;void *scratch=0,*lease_context;uint32_t token=0;int rc,(*lease)(void *);if(!ready(p)||!p->write_armed)return FM1_PROVISION_DENIED;lease=p->arm_valid;lease_context=p->arm_context;p->write_armed=0;p->arm_valid=0;p->arm_context=0;if(!lease||lease(lease_context)!=1||!id_valid(request)||request->base!=p->identity->base||request->root!=p->identity->root||request->peer!=p->identity->peer||memcmp(request->domain,p->identity->domain,16)||memcmp(request->generation,p->identity->generation,32)){fm1_provision_disarm(p);return FM1_PROVISION_DENIED;}if(p->ops->begin(p->ops->context,1,&n,&scratch,&token)!=1){fm1_provision_disarm(p);if(p->ops->faulted(p->ops->context)){p->fault=1;return FM1_PROVISION_FAULT;}return FM1_PROVISION_IO;}if(!token||!scratch_safe(p,n,scratch)||overlap(scratch,PFS_SECTOR,request,sizeof *request)||!matches(p->identity,n)||lease(lease_context)!=1||p->ops->permit_provision(p->ops->context,n,scratch)!=1||lease(lease_context)!=1||!matches(p->identity,n)){fm1_provision_disarm(p);return finish(p,token,FM1_PROVISION_DENIED);}fm1_provision_disarm(p);rc=pns_provision(n,scratch)==PNS_OK?FM1_PROVISION_OK:FM1_PROVISION_IO;return finish(p,token,rc);}
static int secret_valid(const uint8_t *s){uint32_t i,v=0;if(!s)return 0;for(i=0;i<32;i++)v|=s[i];return v!=0;}
static int hmac(const uint8_t *key,const uint8_t *tag,uint32_t tag_n,const uint8_t *data,uint32_t n,uint8_t out[32]){uint8_t pad[64],inner[32];fm1_pattern_sha256 c;uint32_t i;for(i=0;i<64;i++)pad[i]=(uint8_t)((i<32?key[i]:0)^0x36u);if(fm1_pattern_sha256_init(&c)||fm1_pattern_sha256_update(&c,pad,64)||fm1_pattern_sha256_update(&c,tag,tag_n)||fm1_pattern_sha256_update(&c,data,n)||fm1_pattern_sha256_final(&c,inner))return 0;for(i=0;i<64;i++)pad[i]=(uint8_t)((i<32?key[i]:0)^0x5cu);if(fm1_pattern_sha256_init(&c)||fm1_pattern_sha256_update(&c,pad,64)||fm1_pattern_sha256_update(&c,inner,32)||fm1_pattern_sha256_final(&c,out))return 0;memset(pad,0,sizeof pad);memset(inner,0,sizeof inner);return 1;}
static void put32(uint8_t *,uint32_t);
static int challenge_lease(void *ctx){fm1_provision_protocol *p=ctx;return ready(p)&&p->challenge_live&&p->ops->now_ms&&p->ops->safe_state&&p->ops->context_epoch&&p->ops->context_epoch(p->ops->context)==p->challenge_epoch&&p->ops->safe_state(p->ops->context)==1&&(uint32_t)(p->ops->now_ms(p->ops->context)-p->challenge_at)<5000u;}
int fm1_provision_challenge(fm1_provision_protocol *p,const uint8_t nonce[16],uint8_t out[32]){static const uint8_t tag[]="FM1-PROVISION-CHALLENGE-v1";uint8_t msg[72];uint32_t now;if(!ready(p)||!secret_valid(p->secret)||!p->ops->now_ms||!p->ops->safe_state||!p->ops->context_epoch||!nonce||!out||p->ops->safe_state(p->ops->context)!=1||overlap(out,32,p,sizeof *p)||overlap(out,32,p->identity,sizeof *p->identity)||overlap(out,32,p->ops,sizeof *p->ops)||overlap(out,32,p->secret,32)||overlap(out,32,nonce,16)||overlap(nonce,16,p,sizeof *p)||overlap(nonce,16,p->identity,sizeof *p->identity)||overlap(nonce,16,p->ops,sizeof *p->ops)||overlap(nonce,16,p->secret,32))return FM1_PROVISION_DENIED;fm1_provision_disarm(p);if(p->challenge_counter==UINT32_MAX)return FM1_PROVISION_DENIED;now=p->ops->now_ms(p->ops->context);memcpy(msg,p->identity->domain,16);memcpy(msg+16,p->identity->generation,32);memcpy(msg+48,nonce,16);put32(msg+64,++p->challenge_counter);put32(msg+68,now);if(!hmac(p->secret,tag,sizeof tag-1u,msg,sizeof msg,p->challenge))return FM1_PROVISION_DENIED;p->challenge_at=now;p->challenge_epoch=p->ops->context_epoch(p->ops->context);p->challenge_live=1;memcpy(out,p->challenge,32);return FM1_PROVISION_OK;}
int fm1_provision_hmac_arm(fm1_provision_protocol *p,const uint8_t response[32]){static const uint8_t tag[]="FM1-PROVISION-ARM-v1";uint8_t expected[32],difference=0;uint32_t i;if(!p||!response||!secret_valid(p->secret)||overlap(response,32,p,sizeof *p)||overlap(response,32,p->identity,sizeof *p->identity)||overlap(response,32,p->ops,sizeof *p->ops)||overlap(response,32,p->secret,32)||!challenge_lease(p)||!hmac(p->secret,tag,sizeof tag-1u,p->challenge,32,expected)){fm1_provision_disarm(p);return FM1_PROVISION_DENIED;}for(i=0;i<32;i++)difference|=(uint8_t)(expected[i]^response[i]);memset(expected,0,sizeof expected);if(difference||fm1_provision_arm_once(p,challenge_lease,p)!=FM1_PROVISION_OK){fm1_provision_disarm(p);return FM1_PROVISION_DENIED;}return FM1_PROVISION_OK;}
static uint32_t get32(const uint8_t *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static void put32(uint8_t *p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}
int fm1_provision_dispatch(fm1_provision_protocol *p,uint8_t cmd,const uint8_t *body,size_t n,uint8_t *reply,size_t cap,size_t *out){fm1_provision_identity id;int blank,rc;if(!out||(p&&(overlap(out,sizeof *out,p,sizeof *p)||(p->identity&&overlap(out,sizeof *out,p->identity,sizeof *p->identity))||(p->ops&&overlap(out,sizeof *out,p->ops,sizeof *p->ops))||(p->secret&&overlap(out,sizeof *out,p->secret,32))))||(body&&overlap(out,sizeof *out,body,n))||(reply&&overlap(out,sizeof *out,reply,cap)))return FM1_PROVISION_DENIED;*out=0;if(cmd==0xd0u){if(n||!reply||cap<60||!ready(p)||overlap(reply,60,p,sizeof *p)||overlap(reply,60,p->identity,sizeof *p->identity)||overlap(reply,60,p->ops,sizeof *p->ops)||(p->secret&&overlap(reply,60,p->secret,32)))return FM1_PROVISION_DENIED;rc=fm1_provision_identity_read(p,&id);if(rc)return rc;memcpy(reply,id.domain,16);memcpy(reply+16,id.generation,32);put32(reply+48,id.base);put32(reply+52,id.root);put32(reply+56,id.peer);*out=60;return FM1_PROVISION_OK;}if(cmd==0xd1u){if(n!=4||!body||!reply||cap<33)return FM1_PROVISION_DENIED;rc=provision_sector(p,get32(body),&blank,reply+1,reply,33);if(rc)return rc;reply[0]=(uint8_t)blank;*out=33;return FM1_PROVISION_OK;}if(cmd==0xd3u){if(n!=16||!body||!reply||cap<32){fm1_provision_disarm(p);return FM1_PROVISION_DENIED;}rc=fm1_provision_challenge(p,body,reply);if(rc)return rc;*out=32;return FM1_PROVISION_OK;}if(cmd==0xd4u){if(n!=32||!body){fm1_provision_disarm(p);return FM1_PROVISION_DENIED;}return fm1_provision_hmac_arm(p,body);}if(cmd==0xd2u){if(n!=60||!body){fm1_provision_disarm(p);return FM1_PROVISION_DENIED;}memcpy(id.domain,body,16);memcpy(id.generation,body+16,32);id.base=get32(body+48);id.root=get32(body+52);id.peer=get32(body+56);return fm1_provision_commit(p,&id);}return FM1_PROVISION_DENIED;}

#if defined(FM1_PATTERN_IDENTITY_PINNED) && FM1_PATTERN_IDENTITY_PINNED
#include "fm1_pattern_identity_generated.h"
static const fm1_provision_identity embedded_identity={FM1_PROVISION_DOMAIN_INIT,FM1_PROVISION_GENERATION_INIT,0x97000u,FM1_PROVISION_ROOT_INDEX,FM1_PROVISION_PEER_INDEX};
static const uint8_t embedded_secret[32]=FM1_PROVISION_SECRET_INIT;
const fm1_provision_identity *fm1_provision_embedded_identity(void){return &embedded_identity;}
const uint8_t *fm1_provision_embedded_secret(void){return embedded_secret;}
#else
const fm1_provision_identity *fm1_provision_embedded_identity(void){return 0;}
const uint8_t *fm1_provision_embedded_secret(void){return 0;}
#endif
static fm1_provision_protocol *runtime;
int fm1_provision_runtime_bind(fm1_provision_protocol *p){if(runtime||!ready(p)||p->write_armed||p->challenge_live||p->arm_valid)return 0;
#if defined(FM1_DEVICE)
 if(!fm1_provision_embedded_identity()||p->identity!=fm1_provision_embedded_identity()||p->secret!=fm1_provision_embedded_secret())return 0;
#endif
 runtime=p;return 1;}
int fm1_provision_runtime_dispatch(uint8_t cmd,const uint8_t *body,size_t n,uint8_t *reply,size_t cap,size_t *out){return fm1_provision_dispatch(runtime,cmd,body,n,reply,cap,out);}
